class Aggregator:
        """Calculates statistics over metric data points."""

        def __init__(self, filter_tags: Optional[dict[str, str]] = None) -> None:
            self.filter_tags = filter_tags
            self.data = []

        def add_data_point(self, point: MetricPoint) -> None:
            """Adds a metric data point."""
            if self.filter_tags is not None and not any(tag in point.tags for tag in self.filter_tags):
                return
            self.data.append(point)

        def count(self) -> int:
            return len([point for point in self.data if self.filter_tags is None or any(tag in point.tags for tag in self.filter_tags)])

        def sum(self) -> float:
            return sum([point.value for point in self.data if self.filter_tags is None or any(tag in point.tags for tag in self.filter_tags)])

        def avg(self) -> float:
            return sum([point.value for point in self.data if self.filter_tags is None or any(tag in point.tags for tag in self.filter_tags)]) / len(self.data)

        def min(self) -> float:
            return min([point.value for point in self.data if self.filter_tags is None or any(tag in point.tags for tag in self.filter_tags)])

        def max(self) -> float:
            return max([point.value for point in self.data if self.filter_tags is None or any(tag in point.tags for tag in self.filter_tags)])
